<style scoped lang="scss" src="./selection-menu.scss"></style>
<style scoped lang="scss" src="../table/table.scss"></style>
<style scoped lang="scss" src="./selection-menu-gms-donor.scss"></style>
<style scoped lang="scss" src="./selection-menu-gms-period.scss"></style>
<style scoped lang="scss" src="./selection-menu-gms-nav.scss"></style>
<style scoped lang="scss" src="./selection-menu-gms-report.scss"></style>
<style scoped lang="scss" src="./selection-menu-gms-time.scss"></style>
<style scoped lang="scss" src="./selection-menu-gms-save.scss"></style>
<style scoped lang="scss" src="./selection-menu-date-picker.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon.vue";
import { IconShape } from "../icon/icon.constants";
import DropdownMenu from "../../components/dropdown-menu/dropdown-menu";
import { DropdownMenuMode } from "../dropdown-menu/dropdown.constants";
import { OptionMode, SelectionMenuMode } from "./selection-menu.constants";

const modeToClass = {
  [SelectionMenuMode.DEFAULT]: "",
  [SelectionMenuMode.GMS_DONOR]: "SelectionMenu_GMS_Donor",
  [SelectionMenuMode.GMS_PERIOD]: "SelectionMenu_GMS_Period",
  [SelectionMenuMode.GMS_NAV]: "SelectionMenu_GMS_Nav",
  [SelectionMenuMode.GMS_REPORT]: "SelectionMenu_GMS_Report",
  [SelectionMenuMode.GMS_TIME]: "SelectionMenu_GMS_Time",
  [SelectionMenuMode.GMS_SAVE]: "SelectionMenu_GMS_Save",
  [SelectionMenuMode.DATE_PICKER]: "SelectionMenu_Date_Picker",
};

const modeToIconColor = {
  [OptionMode.PRIMARY]: "#ffffff",
  [OptionMode.SECONDARY]: "#2356F6",
};

const modeToArrowColor = {
  [OptionMode.PRIMARY]: "#f9fafb",
  [OptionMode.SECONDARY]: "#2356F6",
};

/**
 * This is Selection Menu the user can use to select an option within a list of
 * options. This accomplishes this via displaying a Dropdown with the options to
 * select.
 */
@Component({
  components: {
    Icon,
    DropdownMenu,
  },
})
export default class SelectionMenu extends Vue {
  /**
   * The default value selected for the menu. Must match a value listed in the
   * dropdown.
   */
  @Prop({ type: [Number, String, Array], default: "" }) defaultValue;
  /** The values provided in the dropdown { label: string, value: any } */
  @Prop({ type: Array, default: () => [] }) values;
  /** Rendering mode of the selection menu */
  @Prop({
    type: String,
    default: SelectionMenuMode.DEFAULT,
  })
  mode;
  /** Specifies how many items can show at a time in the dropdown */
  @Prop({ type: Number, default: 5 }) maxRows;
  /** Makes the property unchangeable */
  @Prop({ type: Boolean, default: false }) readOnly;
  /** Max width the header of the menu will display on the page */
  @Prop({ type: [Number, String] }) maxWidth;
  /**
   * Adds some extra girth to the dropdown menu. Useful for squeezed scenarios
   */
  @Prop({ type: Number }) menuPadding;

  @Prop({ type: Number }) icon;
  /** A placeholder message to appear when no value is selected */
  @Prop({ type: String }) placeholder;
  @Prop({ type: Boolean, default: true }) showArrow;
  @Prop({ type: Boolean, default: false }) showSearch;
  @Prop({ type: Boolean, default: false }) multiSelect;

  focused = false;
  hovered = false;
  value = { label: undefined, value: undefined };
  selectedMap = new Map();
  selectedOptions = [];
  selectedSize = 0;
  error = "error";
  label = "label";

  multiline = false;
  isPassword = false;

  decal = {
    shape: IconShape.CHEVRON_UP,
    size: 20,
  };

  menuBox = null;
  DropdownMenuMode = DropdownMenuMode;
  wasOpen = false;

  preDefaultValue;

  beforeMount() {
    this.preDefaultValue = this.defaultValue;
    this.value = this.values.find((v) => v.value === this.defaultValue);
    this.value = this.value || this.values[0];

    // if defaultValue has been provided and if it's a multiselect selection menu
    if (this.defaultValue && this.multiSelect) {
      // if it's a multiselect, multiple values can be preselected
      if (Array.isArray(this.defaultValue) && this.defaultValue.length > 0) {
        const defaultValues = this.defaultValue.slice();
        defaultValues.forEach((val) =>
          this.selectedMap.set(
            val,
            this.values.find((v) => v.value === val)
          )
        );
      } else {
        this.selectedMap.set(this.defaultValue, this.value);
      }
      this.selectedOptions = Array.from(this.selectedMap.values());
      this.selectedSize = this.selectedMap.size;
    }
  }

  beforeUpdate() {
    if (this.defaultValue !== this.preDefaultValue) {
      this.preDefaultValue = this.defaultValue;
      this.value = this.values.find((v) => v.value === this.defaultValue);
      this.value = this.value || this.values[0];
    }
  }

  mounted() {
    /**
     * Initial emit of the value applied to the field.
     */
    if (this.multiSelect) {
      if (this.selectedMap.size > 0) {
        this.$emit("change", Array.from(this.selectedMap.values()));
      }
    } else {
      if (this.value) this.$emit("change", this.value.value, this.value);
    }
  }

  get currentState() {
    return {
      focused: this.focused,
      hovered: this.hovered,
      value: this.value,
      error: this.error,
    };
  }

  get menuValue() {
    if (this.multiSelect) {
      return Array.from(this.selectedMap.values());
    }

    return this.value;
  }

  get modeClass() {
    return modeToClass[this.mode];
  }

  get headerClass() {
    if (
      this.mode === SelectionMenuMode.GMS_DONOR &&
      this.value &&
      this.value.mode
    ) {
      return `SelectionMenu__Header--${this.value.mode}`;
    }

    return "";
  }

  get headerStateClass() {
    if (this.opened) return "SelectionMenu__Header--open";

    return "";
  }

  get IconShape() {
    return IconShape;
  }

  get stateClass() {
    // if (this.readOnly) return "SelectionMenu--readonly";
    if (this.focused) return "SelectionMenu--focus";
    if (this.hovered) return "SelectionMenu--hovered";
    return "";
  }

  get filledClass() {
    if (this.value) return "SelectionMenu--filled";
    return "SelectionMenu--empty";
  }

  get selectionLabel() {
    if (this.multiSelect && this.selectedSize > 0) {
      return Array.from(this.selectedMap.values())
        .map((v) => v.label)
        .sort((a, b) => a.localeCompare(b))
        .join(", ");
    }

    return this.value?.label || "";
  }

  get showPlaceholder() {
    return this.multiSelect
      ? this.selectedSize === 0
      : this.value === undefined;
  }

  get headerIconShape() {
    if (this.icon !== undefined) return this.icon;

    return this.value?.icon || undefined;
  }

  get headerIconColor() {
    if (
      this.mode === SelectionMenuMode.GMS_DONOR &&
      this.value &&
      this.value.mode
    ) {
      return modeToIconColor[this.value.mode];
    }

    return "#2356f6";
  }

  get arrowColor() {
    if (
      this.mode === SelectionMenuMode.GMS_DONOR &&
      this.value &&
      this.value.mode
    ) {
      return modeToArrowColor[this.value.mode];
    } else if (
      this.mode === SelectionMenuMode.GMS_REPORT ||
      this.mode === SelectionMenuMode.GMS_SAVE
    ) {
      return "#000000";
    } else if (this.mode === SelectionMenuMode.DATE_PICKER) {
      return "#408DD7";
    }

    return "#2356f6";
  }

  get dropdownValue() {
    return this.value?.value;
  }

  get dropdownMode() {
    if (this.mode === SelectionMenuMode.GMS_DONOR) {
      return DropdownMenuMode.GMS_DONOR;
    }

    if (this.mode === SelectionMenuMode.GMS_PERIOD) {
      return DropdownMenuMode.GMS_PERIOD;
    }

    if (this.mode === SelectionMenuMode.GMS_NAV) {
      return DropdownMenuMode.GMS_NAV;
    }

    if (this.mode === SelectionMenuMode.GMS_TIME) {
      return DropdownMenuMode.GMS_TIME;
    }

    if (this.mode === SelectionMenuMode.DATE_PICKER) {
      return DropdownMenuMode.DATE_PICKER;
    }

    return DropdownMenuMode.DEFAULT;
  }

  get opened() {
    return Boolean(this.menuBox);
  }

  get headerStyle() {
    if (this.maxWidth) {
      return {
        width: "100%",
        maxWidth: `${this.maxWidth}px`,
      };
    }

    return {
      width: "auto",
    };
  }

  handleFocus() {
    this.focused = true;
  }

  handleBlur() {
    this.focused = false;
  }

  handleOver() {
    this.hovered = true;
  }

  handleOut() {
    this.hovered = false;
  }

  handleClick() {
    if (!this.$refs.container) return;

    if (this.menuBox || this.wasOpen || this.readOnly) {
      this.menuBox = undefined;
    } else {
      const box = this.$refs.container.getBoundingClientRect();
      this.menuBox = {
        left: box.x,
        top: box.y,
        width: box.width + (this.menuPadding || 0),
        height: box.height,
        right: box.right + (this.menuPadding || 0),
        bottom: box.bottom,
      };
    }
  }

  handleMouseDown() {
    this.wasOpen = Boolean(this.menuBox);
  }

  handleSelect(val) {
    if (!this.readOnly) {
      if (this.multiSelect) {
        if (this.selectedMap.has(val.value)) {
          this.selectedMap.delete(val.value);
        } else {
          this.selectedMap.set(val.value, val);
        }

        this.selectedSize = this.selectedMap.size;
        this.selectedOptions = Array.from(this.selectedMap.values());
        this.$forceUpdate();
      } else {
        this.value = val;
      }
    }
    if (this.menuBox && !this.multiSelect) this.menuBox = undefined;

    /**
     * Change input event. Fires when the value of this field changes and
     * provides the current value. As well as the value option.
     *
     * @event change
     */
    if (this.multiSelect) {
      this.$emit("change", Array.from(this.selectedMap.values()));
    } else {
      this.$emit("change", this.value.value, this.value);
    }
  }

  handleClose() {
    if (this.menuBox) this.menuBox = undefined;
  }
}
</script>

<template>
  <div
    :class="[
      'SelectionMenu',
      modeClass,
      filledClass,
      stateClass,
      readOnly ? 'SelectionMenu--readonly' : '',
    ]"
    ref="container"
    :style="headerStyle"
  >
    <div
      :class="['SelectionMenu__Header', headerClass, headerStateClass]"
      @mouseover="handleOver"
      @mouseout="handleOut"
      @click="handleClick"
      @mousedown="handleMouseDown"
    >
      <div class="SelectionMenu__HeaderLeft">
        <div
          v-if="headerIconShape !== undefined"
          class="SelectionMenu__HeaderIcon"
        >
          <Icon :shape="headerIconShape" :size="20" :color="headerIconColor" />
        </div>
        <div v-if="showPlaceholder" class="SelectionMenu__Placeholder">
          <span>{{ placeholder }}</span>
        </div>
        <div v-else class="SelectionMenu__HeaderLabel">
          <span>{{ selectionLabel }}</span>
        </div>
      </div>
      <div class="SelectionMenu__HeaderRight">
        <div
          v-if="this.value && this.value.favourite !== undefined"
          class="SelectionMenu__Favourite"
        >
          <Icon
            v-if="this.value.favourite === true"
            :shape="IconShape.STAR_FULL"
            :size="24"
            :color="'#57bfa1'"
          />
          <Icon
            v-else-if="this.value.favourite === false"
            :shape="IconShape.STAR_EMPTY"
            :size="24"
            :color="'#57bfa1'"
          />
        </div>
        <div v-if="!readOnly && showArrow" class="SelectionMenu__Arrow">
          <Icon
            v-if="opened"
            :shape="IconShape.CHEVRON_UP"
            :size="decal.size"
            :color="arrowColor"
          />
          <Icon
            v-else
            :shape="IconShape.CHEVRON_DOWN"
            :size="decal.size"
            :color="arrowColor"
          />
        </div>
      </div>
    </div>

    <DropdownMenu
      v-if="opened"
      :mode="dropdownMode"
      :maxRows="maxRows"
      :bounds="menuBox"
      :value="dropdownValue"
      :values="values"
      :multiSelect="multiSelect"
      :selectedOptions="selectedOptions"
      :coverBounds="true"
      :showSearch="showSearch"
      @select="handleSelect"
      @close="handleClose"
    />
  </div>
</template>
